"use client"

import * as React from "react"
import { cn } from "cn"

import { Badge } from "@/components/ui/badge"
import { LinkButton } from "@/components/ui/button"
import { Icon } from "@/components/ui/icon"
import { SemanticContent } from "@/components/ui/semantic-content"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"

type Plan = {
  name: string
  description?: string
  price?: string
  priceByInterval?: { interval: string; amount: number; priceText: string }[]
  features?: string[]
  badge?: string
  highlight?: boolean
  cta: { label: string; href: string }
}

/**
 * tailark mist pricing-1 rebuilt for aria: plans side by side, an interval
 * toggle (aria-nova ToggleGroup) and each plan's call to action as the
 * aria-nova LinkButton in place of Button asChild + next/link.
 */
export default function Pricing({
  heading = "Pricing that scales with you",
  description = "Pick a plan to start. Switch or cancel at any time.",
  intervals = ["Monthly", "Yearly"],
  plans = [
    {
      name: "Starter",
      description: "For individuals getting set up",
      priceByInterval: [
        { interval: "Monthly", amount: 0, priceText: "$0" },
        { interval: "Yearly", amount: 0, priceText: "$0" },
      ],
      features: ["One workspace", "Community support", "Core components"],
      cta: { label: "Start free", href: "#" },
    },
    {
      name: "Team",
      description: "For teams shipping together",
      badge: "Popular",
      highlight: true,
      priceByInterval: [
        { interval: "Monthly", amount: 24, priceText: "$24" },
        { interval: "Yearly", amount: 240, priceText: "$240" },
      ],
      features: ["Unlimited workspaces", "Priority support", "Every section and frame"],
      cta: { label: "Get started", href: "#" },
    },
  ],
}: {
  heading?: string
  description?: string
  intervals?: string[]
  plans?: Plan[]
}) {
  const [interval, setInterval] = React.useState(intervals[0])
  return (
    <section data-slot="pricing" className="bg-muted py-16 md:py-20">
      <div className="mx-auto max-w-5xl px-6">
        <div className="mx-auto max-w-2xl text-center">
          <SemanticContent as="h2" className="md:text-4xl lg:text-5xl">{heading}</SemanticContent>
          <SemanticContent as="p" className="mx-auto mt-4 max-w-md text-lg text-muted-foreground">{description}</SemanticContent>
        </div>
        {intervals.length > 1 && (
          <div className="mt-8 flex justify-center">
            <ToggleGroup
              aria-label="Billing interval"
              variant="outline"
              selectionMode="single"
              disallowEmptySelection
              selectedKeys={[interval]}
              onSelectionChange={(keys) => {
                const next = [...keys][0]
                if (next !== undefined) setInterval(String(next))
              }}
            >
              {intervals.map((i) => (
                <ToggleGroupItem key={i} id={i}>
                  {i}
                </ToggleGroupItem>
              ))}
            </ToggleGroup>
          </div>
        )}
        <div className="mt-8 grid gap-6 md:mt-12 md:grid-cols-2">
          {plans.map((plan) => {
            const price = plan.priceByInterval?.find((p) => p.interval === interval)?.priceText ?? plan.price
            return (
              <div
                key={plan.name}
                data-highlight={plan.highlight || undefined}
                className={cn(
                  "flex flex-col gap-6 rounded-xl border border-border bg-background p-8",
                  plan.highlight && "ring-2 ring-primary"
                )}
              >
                <div className="space-y-2">
                  <div className="flex items-center gap-2">
                    <SemanticContent as="h3" className="text-xl">{plan.name}</SemanticContent>
                    {plan.badge && <Badge>{plan.badge}</Badge>}
                  </div>
                  {plan.description && <SemanticContent as="p" className="text-muted-foreground">{plan.description}</SemanticContent>}
                </div>
                {price && (
                  <SemanticContent as="p" className="text-5xl font-semibold tracking-tight">
                    {price}
                    <SemanticContent as="small" className="ml-1 text-base font-normal">/ {interval.toLowerCase()}</SemanticContent>
                  </SemanticContent>
                )}
                {plan.features && (
                  <ul role="list" className="space-y-3 text-sm">
                    {plan.features.map((f) => (
                      <li key={f} className="flex items-center gap-2">
                        <Icon name="check" size="sm" className="text-primary" />
                        <span>{f}</span>
                      </li>
                    ))}
                  </ul>
                )}
                <LinkButton href={plan.cta.href} size="lg" variant={plan.highlight ? "default" : "outline"} className="mt-auto">
                  {plan.cta.label}
                </LinkButton>
              </div>
            )
          })}
        </div>
      </div>
    </section>
  )
}
